/** A clip of the pack: any name a theme array of characters.ts may list. */
export type KitClip = keyof typeof CLIP_FILE;

/** The files that hold the given clips, without repeats, in `ANIM_FILES` order. */
export function animFilesFor(clips: readonly KitClip[]): AnimFile[] {
  const used = new Set<AnimFile>(clips.map((c) => CLIP_FILE[c]));
  return ANIM_FILES.filter((f) => used.has(f));
}
